const NAME_RE = /^[A-Za-z0-9_./:-]+$/

function isValidName(s) {
  return NAME_RE.test(s)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

function splitWhitespace(s) {
  return s.split(/\s+/).filter((t) => t.length > 0)
}

function parseIntField(token, fieldName, min, lineNo) {
  if (!/^(0|[1-9][0-9]*)$/.test(token)) {
    throw new ParseError(lineNo, `${fieldName} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < BigInt(min)) {
    throw new ParseError(lineNo, `${fieldName} must be an integer of at least ${min}`)
  }
  return value
}

export function parse(text) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = splitWhitespace(trimmed)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket') {
      if (seenEvent) {
        throw new ParseError(lineNo, 'declarations must come before the first event')
      }
      if (rest.length !== 4) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [name, capacityTok, refillTok, perTok] = rest
      if (!isValidName(name)) {
        throw new ParseError(lineNo, `invalid policy name ${name}`)
      }
      const capacity = parseIntField(capacityTok, 'capacity', 1, lineNo)
      const refill = parseIntField(refillTok, 'refill', 0, lineNo)
      const per = parseIntField(perTok, 'per', 1, lineNo)
      if (policies.has(name)) {
        throw new ParseError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (seenEvent) {
        throw new ParseError(lineNo, 'declarations must come before the first event')
      }
      if (rest.length !== 3) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [name, limitTok, spanTok] = rest
      if (!isValidName(name)) {
        throw new ParseError(lineNo, `invalid policy name ${name}`)
      }
      const limit = parseIntField(limitTok, 'limit', 0, lineNo)
      const span = parseIntField(spanTok, 'span', 1, lineNo)
      if (policies.has(name)) {
        throw new ParseError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (seenEvent) {
        throw new ParseError(lineNo, 'declarations must come before the first event')
      }
      if (rest.length < 2) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = rest[0]
      const policyNames = rest.slice(1)
      if (!isValidName(prefix)) {
        throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      }
      for (const pName of policyNames) {
        if (!isValidName(pName)) {
          throw new ParseError(lineNo, `invalid policy name ${pName}`)
        }
        if (!policies.has(pName)) {
          throw new ParseError(lineNo, `unknown policy ${pName}`)
        }
      }
      if (routePrefixes.has(prefix)) {
        throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (rest.length !== 2) {
        throw new ParseError(lineNo, 'expected event <tick> <key>')
      }
      const [tickTok, key] = rest
      const tick = parseIntField(tickTok, 'tick', 0, lineNo)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      if (!isValidName(key)) {
        throw new ParseError(lineNo, `invalid key ${key}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ line: lineNo, tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

