export class TokenBucketPolicy {
  constructor(spec) {
    this.capacity = spec.capacity // BigInt
    this.refill = spec.refill // BigInt
    this.per = spec.per // BigInt
    this.states = new Map() // key -> { scaled: BigInt, lastTick: BigInt }
  }

  _stateFor(key) {
    let s = this.states.get(key)
