 * Runs the parsed events against the parsed policies and routes, producing
 * one verdict per event in log order.
 */

import { makePolicy } from './policies.js'

function findRoute(routes, key) {
  let best = null
  for (const r of routes) {
    if (key.startsWith(r.prefix)) {
      if (best === null || r.prefix.length > best.prefix.length) {
        best = r
      }
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const instances = new Map()
  for (const [name, spec] of policies) {
    instances.set(name, makePolicy(spec))
  }

  // Sort routes so the longest prefixes are checked first (not strictly
  // required by findRoute, but keeps behaviour obvious).
  const sortedRoutes = [...routes].sort((a, b) => b.prefix.length - a.prefix.length)

  const verdicts = []

  for (const ev of events) {
    const route = findRoute(sortedRoutes, ev.key)
    if (route === null) {
      verdicts.push({ tick: ev.tick, key: ev.key, allow: true, deniedBy: null })
      continue
    }
    const policyList = route.policyNames.map((n) => instances.get(n))
    for (const p of policyList) {
      p.advance(ev.key, ev.tick)
    }
    let deniedBy = null
    for (let i = 0; i < policyList.length; i++) {
      if (!policyList[i].allows(ev.key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }
    if (deniedBy === null) {
      for (const p of policyList) {
        p.record(ev.key, ev.tick)
      }
      verdicts.push({ tick: ev.tick, key: ev.key, allow: true, deniedBy: null })
    } else {
      verdicts.push({ tick: ev.tick, key: ev.key, allow: false, deniedBy })
    }
  }

  return verdicts
}
"}

