chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-gc7MtV/src/format.js","content":"/**
 * Renders verdicts into the two output modes.
 */

export function formatReplay(verdicts) {
  const lines = []
  for (const v of verdicts) {
    if (v.allow) {
      lines.push(`${v.tick} ${v.key} allow`)
    } else {
      lines.push(`${v.tick} ${v.key} deny ${v.deniedBy}`)
    }
  }
  return lines.length > 0 ? lines.join('\n') + '\n' : ''
}

export function formatSummary(verdicts) {
  const perKey = new Map() // key -> { allowed, denied }
  let totalAllowed = 0
  let totalDenied = 0

  for (const v of verdicts) {
    let entry = perKey.get(v.key)
    if (entry === undefined) {
      entry = { allowed: 0, denied: 0 }
      perKey.set(v.key, entry)
    }
    if (v.allow) {
      entry.allowed++
      totalAllowed++
    } else {
      entry.denied++
      totalDenied++
    }
  }

  const keys = [...perKey.keys()].sort()
  const lines = []
  for (const key of keys) {
    const e = perKey.get(key)
    lines.push(`${key} allowed=${e.allowed} denied=${e.denied}`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines.join('\n') + '\n'
}
"}

